import 'package:flutter/material.dart';import '../domain/models/contact.dart';import '../data/contact_service.dart';import '../data/contact_group_service.dart';import '../../../core/mesh/mesh_router.dart';class ContactCardScreen extends StatefulWidget {  final Contact contact;  final ContactService contactService;  final ContactGroupService groupService;  final MeshRouter? meshRouter;  final VoidCallback? onCall;  final VoidCallback? onVideoCall;  final VoidCallback? onMessage;  final VoidCallback? onLocation;  final VoidCallback? onFile;  final VoidCallback? onSOS;  const ContactCardScreen({    super.key,    required this.contact,    required this.contactService,    required this.groupService,    this.meshRouter,    this.onCall,    this.onVideoCall,    this.onMessage,    this.onLocation,    this.onFile,    this.onSOS,  });  @override  State<ContactCardScreen> createState() => _ContactCardScreenState();}class _ContactCardScreenState extends State<ContactCardScreen> {  late Contact _contact;  late List<ContactGroupModel> _contactGroups;  @override  void initState() {    super.initState();    _contact = widget.contact;    _loadGroups();  }  void _loadGroups() {    _contactGroups = widget.groupService.getGroupsForContact(_contact.deviceId);  }  Color _getStatusColor() {    switch (_contact.status) {      case ContactStatus.nearby:        return Colors.green;      case ContactStatus.viaRelay:        return Colors.orange;      case ContactStatus.unreachable:        return Colors.grey;    }  }  String _getStatusText() {    switch (_contact.status) {      case ContactStatus.nearby:        return 'Nearby';      case ContactStatus.viaRelay:        final hops = widget.meshRouter?.getHopCount(_contact.deviceId) ?? -1;        return hops > 0 ? 'Reachable via $hops hops' : 'Reachable via relay';      case ContactStatus.unreachable:        return 'Offline';    }  }  String _getChannelText() {    final channel =        widget.meshRouter?.getBestChannel(_contact.deviceId) ?? 'none';    switch (channel) {      case 'ble':        return 'BLE Direct';      case 'wifi':        return 'WiFi Direct';      case 'relay':        return 'Mesh Relay';      case 'lora':        return 'LoRa';      default:        return 'Not connected';    }  }  Future<void> _editContact() async {    final nameController = TextEditingController(text: _contact.name);    final callsignController =        TextEditingController(text: _contact.callsign ?? '');    await showDialog(      context: context,      builder: (ctx) => AlertDialog(        title: const Text('Edit Contact'),        content: Column(          mainAxisSize: MainAxisSize.min,          children: [            TextField(              controller: nameController,              decoration: const InputDecoration(labelText: 'Name'),            ),            const SizedBox(height: 8),            TextField(              controller: callsignController,              decoration:                  const InputDecoration(labelText: 'Callsign (optional)'),            ),          ],        ),        actions: [          TextButton(            onPressed: () => Navigator.pop(ctx),            child: const Text('Cancel'),          ),          FilledButton(            onPressed: () async {              final updated = _contact.copyWith(                name: nameController.text,                callsign: callsignController.text.isEmpty                    ? null                    : callsignController.text,              );              await widget.contactService.saveContact(updated);              setState(() {                _contact = updated;              });              if (mounted) Navigator.pop(ctx);            },            child: const Text('Save'),          ),        ],      ),    );  }  Future<void> _toggleTrusted() async {    final updated = _contact.copyWith(isTrusted: !_contact.isTrusted);    await widget.contactService.saveContact(updated);    setState(() {      _contact = updated;    });  }  Future<void> _blockContact() async {    final confirmed = await showDialog<bool>(      context: context,      builder: (ctx) => AlertDialog(        title: const Text('Block Contact'),        content: Text(            'Block ${_contact.name}? They will be silenced and cannot contact you.'),        actions: [          TextButton(            onPressed: () => Navigator.pop(ctx, false),            child: const Text('Cancel'),          ),          FilledButton(            style: FilledButton.styleFrom(backgroundColor: Colors.red),            onPressed: () => Navigator.pop(ctx, true),            child: const Text('Block'),          ),        ],      ),    );    if (confirmed == true) {      final updated = _contact.copyWith(isBlocked: true);      await widget.contactService.saveContact(updated);      setState(() {        _contact = updated;      });    }  }  Future<void> _deleteContact() async {    final confirmed = await showDialog<bool>(      context: context,      builder: (ctx) => AlertDialog(        title: const Text('Delete Contact'),        content: Text('Delete ${_contact.name}? This cannot be undone.'),        actions: [          TextButton(            onPressed: () => Navigator.pop(ctx, false),            child: const Text('Cancel'),          ),          FilledButton(            style: FilledButton.styleFrom(backgroundColor: Colors.red),            onPressed: () => Navigator.pop(ctx, true),            child: const Text('Delete'),          ),        ],      ),    );    if (confirmed == true) {      await widget.contactService.deleteContact(_contact.deviceId);      if (mounted) Navigator.pop(context);    }  }  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(        title: const Text('Contact Card'),        actions: [          IconButton(            icon: const Icon(Icons.edit),            onPressed: _editContact,          ),          PopupMenuButton<String>(            onSelected: (value) {              switch (value) {                case 'trusted':                  _toggleTrusted();                  break;                case 'block':                  _blockContact();                  break;                case 'delete':                  _deleteContact();                  break;              }            },            itemBuilder: (ctx) => [              PopupMenuItem(                value: 'trusted',                child: Row(                  children: [                    Icon(                      _contact.isTrusted ? Icons.star : Icons.star_border,                      color: _contact.isTrusted ? Colors.amber : null,                    ),                    const SizedBox(width: 8),                    Text(_contact.isTrusted                        ? 'Remove from Trusted'                        : 'Add to Trusted'),                  ],                ),              ),              const PopupMenuItem(                value: 'block',                child: Row(                  children: [                    Icon(Icons.block),                    SizedBox(width: 8),                    Text('Block Contact'),                  ],                ),              ),              const PopupMenuItem(                value: 'delete',                child: Row(                  children: [                    Icon(Icons.delete, color: Colors.red),                    SizedBox(width: 8),                    Text('Delete', style: TextStyle(color: Colors.red)),                  ],                ),              ),            ],          ),        ],      ),      body: SingleChildScrollView(        child: Column(          children: [            const SizedBox(height: 24),            Stack(              children: [                CircleAvatar(                  radius: 50,                  backgroundColor: Colors.blue.withOpacity(0.2),                  child: Text(                    _contact.avatarEmoji ?? _contact.name[0].toUpperCase(),                    style: const TextStyle(fontSize: 40),                  ),                ),                Positioned(                  bottom: 0,                  right: 0,                  child: Container(                    width: 24,                    height: 24,                    decoration: BoxDecoration(                      color: _getStatusColor(),                      shape: BoxShape.circle,                      border: Border.all(color: Colors.white, width: 3),                    ),                  ),                ),              ],            ),            const SizedBox(height: 16),            Text(              _contact.name,              style: Theme.of(context).textTheme.headlineSmall,            ),            if (_contact.callsign != null)              Text(                _contact.displayCallsign,                style: Theme.of(context).textTheme.titleMedium?.copyWith(                      color: Colors.grey,                      fontFamily: 'monospace',                    ),              ),            const SizedBox(height: 8),            Row(              mainAxisAlignment: MainAxisAlignment.center,              children: [                Icon(Icons.circle, color: _getStatusColor(), size: 12),                const SizedBox(width: 4),                Text(                  _getStatusText(),                  style: TextStyle(color: _getStatusColor()),                ),                if (_contact.isTrusted) ...[                  const SizedBox(width: 16),                  const Icon(Icons.star, color: Colors.amber, size: 16),                  const Text(' Trusted',                      style: TextStyle(color: Colors.amber, fontSize: 12)),                ],              ],            ),            const SizedBox(height: 4),            Text(              _getChannelText(),              style: const TextStyle(fontSize: 12, color: Colors.grey),            ),            const SizedBox(height: 24),            _buildActionGrid(),            const Divider(height: 32),            _buildInfoSection(),            if (_contactGroups.isNotEmpty) ...[              const Divider(height: 32),              _buildGroupsSection(),            ],            const SizedBox(height: 32),          ],        ),      ),    );  }  Widget _buildActionGrid() {    return Padding(      padding: const EdgeInsets.symmetric(horizontal: 32),      child: Row(        mainAxisAlignment: MainAxisAlignment.spaceEvenly,        children: [          _ActionButton(            icon: Icons.message,            label: 'Message',            onTap: widget.onMessage ?? () {},            color: Colors.blue,          ),          _ActionButton(            icon: Icons.call,            label: 'Call',            onTap: widget.onCall ?? () {},            color: Colors.green,          ),          _ActionButton(            icon: Icons.videocam,            label: 'Video',            onTap: widget.onVideoCall ?? () {},            color: Colors.purple,          ),        ],      ),    );  }  Widget _buildActionGrid2() {    return Padding(      padding: const EdgeInsets.symmetric(horizontal: 32, vertical: 16),      child: Row(        mainAxisAlignment: MainAxisAlignment.spaceEvenly,        children: [          _ActionButton(            icon: Icons.location_on,            label: 'Location',            onTap: widget.onLocation ?? () {},            color: Colors.orange,          ),          _ActionButton(            icon: Icons.folder,            label: 'File',            onTap: widget.onFile ?? () {},            color: Colors.teal,          ),          _ActionButton(            icon: Icons.sos,            label: 'SOS',            onTap: widget.onSOS ?? () {},            color: Colors.red,            isSOS: true,          ),        ],      ),    );  }  Widget _buildInfoSection() {    return Padding(      padding: const EdgeInsets.symmetric(horizontal: 16),      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        children: [          const Text(            'CONTACT INFO',            style: TextStyle(                fontSize: 12, color: Colors.grey, fontWeight: FontWeight.bold),          ),          const SizedBox(height: 8),          _InfoTile(            icon: Icons.fingerprint,            title: 'Device ID',            subtitle: _contact.deviceId.substring(0, 16) + '...',          ),          _InfoTile(            icon: Icons.key,            title: 'Public Key',            subtitle: _contact.publicKey.substring(0, 24) + '...',          ),          _InfoTile(            icon: Icons.calendar_today,            title: 'Added',            subtitle: _contact.addedAt.toString().split(' ')[0],          ),        ],      ),    );  }  Widget _buildGroupsSection() {    return Padding(      padding: const EdgeInsets.symmetric(horizontal: 16),      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        children: [          const Text(            'GROUPS',            style: TextStyle(                fontSize: 12, color: Colors.grey, fontWeight: FontWeight.bold),          ),          const SizedBox(height: 8),          Wrap(            spacing: 8,            children: _contactGroups                .map((g) => Chip(                      avatar: Icon(Icons.circle,                          size: 12, color: Color(g.colorValue)),                      label: Text(g.name),                    ))                .toList(),          ),        ],      ),    );  }}class _ActionButton extends StatelessWidget {  final IconData icon;  final String label;  final VoidCallback onTap;  final Color color;  final bool isSOS;  const _ActionButton({    required this.icon,    required this.label,    required this.onTap,    required this.color,    this.isSOS = false,  });  @override  Widget build(BuildContext context) {    return InkWell(      onTap: onTap,      borderRadius: BorderRadius.circular(12),      child: Container(        padding: const EdgeInsets.all(16),        child: Column(          children: [            Container(              padding: const EdgeInsets.all(12),              decoration: BoxDecoration(                color: isSOS                    ? Colors.red.withOpacity(0.2)                    : color.withOpacity(0.1),                shape: BoxShape.circle,              ),              child: Icon(                icon,                color: isSOS ? Colors.red : color,                size: 28,              ),            ),            const SizedBox(height: 8),            Text(              label,              style: TextStyle(                fontSize: 12,                color: isSOS ? Colors.red : color,                fontWeight: isSOS ? FontWeight.bold : FontWeight.normal,              ),            ),          ],        ),      ),    );  }}class _InfoTile extends StatelessWidget {  final IconData icon;  final String title;  final String subtitle;  const _InfoTile({    required this.icon,    required this.title,    required this.subtitle,  });  @override  Widget build(BuildContext context) {    return ListTile(      leading: Icon(icon, color: Colors.grey),      title: Text(title),      subtitle: Text(subtitle, style: const TextStyle(fontSize: 12)),      contentPadding: EdgeInsets.zero,    );  }}extension on Color {  Color get dot => this;}